insert into public.preview_catalogo_maestro_platos (plato_id, sinonimos, resumen, hack, que_observar, activo)
values
('arroz-valenciana', ARRAY['arroz a la valenciana','arroz valenciano','arroz con mariscos y carnes']::text[], 'Un plato complejo que combina carbohidratos de arroz con una mixtura rica de proteínas animales (pollo, cerdo, mariscos) y vegetales dorados.', 'Al ser un plato muy abundante en ingredientes, servite una porción moderada y masticá con calma; la combinación de varias proteínas puede alargar la digestión si se come apurado. Tip extra: un buen golpe de jugo de limón por encima al servir activa las secreciones gástricas y equilibra la densidad de los sabores.', 'Registra la estabilidad de tu energía durante la tarde; al tener una matriz variada, la saciedad suele ser sumamente prolongada.', false),
('paella', ARRAY['paella','paella mixta','paella de mariscos']::text[], 'Joya de la cocina mediterránea. Arroz estacionado con azafrán, vegetales y frutos del mar o carnes magras, con un excelente perfil de micronutrientes.', 'El azafrán puro no solo da el color clásico, sino que aporta compuestos bioactivos que mejoran el confort digestivo y el estado de ánimo. Tip extra: disfrutala sin apuro, saboreando el fondo dorado (socarrat) con moderación si sos sensible a las digestiones pesadas.', 'Analiza tu liviandad estomacal; los mariscos combinados con arroz de buena calidad suelen dar una satisfacción muy limpia sin la modorra típica de las harinas refinadas.', false),
('guiso-arroz', ARRAY['guiso de arroz','arroz con carne y verduras','arrocito guisado']::text[], 'Clásico de olla reconfortante. Arroz cocido en caldo concentrado con verduras de estación y pequeños trozos de carne, logrando una textura melosa y de rápida asimilación.', 'Dejar reposar el guiso unos minutos antes de servir ayuda a que los almidones se estabilicen y no caigan pesados al estómago. Tip extra: sumarle un toque de queso rallado de calidad o perejil fresco al plato realza el perfil nutricional y estimula la digestión.', 'Presta atención al calor y confort que aporta; es un plato que reconforta pero requiere actividad posterior para metabolizar bien su energía rápida.', false),
('guiso-lentejas', ARRAY['guiso de lentejas','lentejas guisadas','guiso criollo de lentejas']::text[], 'El rey indiscutido de los platos de invierno. Aporte masivo de proteína vegetal, hierro y fibra prebiótica gracias a las legumbres.', 'Si las lentejas estuvieron bien remojadas previamente, vas a evitar por completo la hinchazón abdominal típica. El toque fit de valor: sumale un chorrito generoso de vinagre o limón al plato servido y comelo con una hojita de laurel; los ácidos orgánicos potencian la absorción del hierro vegetal y cuidan tu microbiota.', 'Registra el nivel de saciedad extrema que te deja; es un plato de alta densidad que mantiene el hambre a raya durante horas, ideal para días de mucho desgaste.', false),
('guiso-papa', ARRAY['guiso de papa','guiso de papas con carne','estofado de papa']::text[], 'Alimento de olla muy noble, donde la papa absorbe todos los jugos del fondo de cocción, aportando carbohidratos reconfortantes y un nivel calórico moderado.', 'Cocinalas con los cubos de papa enteros para que no se deshagan por completo y mantengan una estructura que obligue a una mínima masticación. Tip extra: un toque de pimentón dulce y cebolla de verdeo picada arriba levanta el plato a otro nivel sin sumar complicaciones.', 'Nota la velocidad de digestión; al ser un plato blando y húmedo, se asimila con muchísima rapidez, por lo que la porción justa es la clave.', false),
('guiso-fideos', ARRAY['guiso de fideos','fideos guisados','tallarines de olla']::text[], 'Fideos cortos cocidos directamente en el caldo con verduras y carne, logrando una salsa espesa y bien integrada por el almidón de la pasta.', 'Al igual que con el arroz de olla, controlar el tamaño de la porción es fundamental para evitar el letargo post-comida propio de las harinas de cocción húmeda. Tip extra: un toque de queso cremoso o rallado al final aporta untuosidad y frena levemente el pico de absorción rápida.', 'Evalúa tu nivel de energía inmediata; te da un envión rápido pero puede pedir movimiento físico para evitar la modorra.', false),
('tortilla-papa', ARRAY['tortilla de papa','tortilla española','tortilla de papas','tortillita']::text[], 'Estructura sólida a base de papa y huevo coagulado, combinando carbohidratos energéticos con una proteína de altísima calidad biológica.', 'Si querés aligerar la cocción tradicional, hacé las papas previamente al horno o vapor antes de unirlas al huevo en la sartén, evitando el exceso de aceite de la fritura previa. Tip extra: acompañada de una buena ensalada de hojas verdes crudas, equilibras perfectamente el plato.', 'Registra tu saciedad; la combinación de huevo y papa es una de las fórmulas más saciantes y estables para mantener el apetito controlado.', false),
('tortilla-acelga', ARRAY['tortilla de acelga','tortilla de verdura','tortilla de espinaca']::text[], 'Versión verde y ligera que reemplaza gran parte del tubérculo por vegetales de hoja unidos por el huevo. Fibra y micronutrientes asegurados.', 'Escurrí muy bien el agua de la acelga antes de batirla con los huevos para que la tortilla no quede húmeda ni se desarme en la sartén. Tip extra: un toque de ajo deshidratado o rallado realza el sabor de la verdura de forma excelente.', 'Analiza tu liviandad estomacal; es una opción sumamente amigable para comer al mediodía y seguir con la mente despejada.', false),
('estofado', ARRAY['estofado','estofado de carne','estofado criollo']::text[], 'Carne vacuna u otro corte cocinado a fuego muy lento en salsa de tomate con verduras, logrando una ternura extrema y una concentración profunda de sabor umami.', 'La cocción lenta predigiere las fibras de la carne, facilitando enormemente el trabajo de tu sistema gástrico. Tip extra: acompañalo con vegetales al vapor o una base liviana en lugar de abusar de grandes cantidades de pan.', 'Nota el confort digestivo profundo y la energía sostenida que te otorga una buena carne bien estofada.', false),
('polenta', ARRAY['polenta','harina de maiz','polenta cremosa']::text[], 'Puré caliente a base de harina de maíz. Aporta carbohidratos de rápida asimilación y una textura sumamente reconfortante.', 'El secreto para que no te tire un bajón de energía: preparala con un toque de caldo real y sumale una buena cucharada de manteca o aceite de oliva al final junto con un buen queso. Las grasas saludables frenan el impacto glucémico directo de la harina de maíz. Tip extra: un toque de pimienta negra despierta el sabor de la polenta instantáneamente.', 'Presta atención a la velocidad con la que digerís la polenta; al ser un carbohidrato puro, su tránsito es rápido y pide un buen acompañamiento proteico.', false),
('humita', ARRAY['humita','humita en olla','humita en chala']::text[], 'Preparación tradicional a base de choclo tierno rallado, zapallo, cebolla y leche o queso, con un perfil de sabor dulce y cremoso muy característico.', 'Al tener una base natural de choclo y zapallo, aporta una fibra muy noble, pero al ser dulce y cremosa, modera la porción si buscás evitar picos de glucosa. Tip extra: un toque de pimentón picante o rehogado de cebolla con ají molido arriba contrasta perfecto con el dulzor del choclo.', 'Registra la sensación de confort y energía cálida; es un plato sumamente reconfortante pero de digestión rápida.', false),
('tamal', ARRAY['tamal','tamales','humita envuelta']::text[], 'Masa de maíz rellena de carne especiada, envuelta y cocida en su propia chala. Alimento ancestral de alta densidad energética y portátil.', 'Por su contenido de masa de maíz y carne especiada, funciona como una comida completa por sí sola; comelo despacio y acompáñalo con agua fresca. Tip extra: un toque de salsa criolla picante por encima realza los sabores y estimula las secreciones digestivas.', 'Nota la saciedad prolongada que otorga; al estar envuelto y compacto, su digestión es pausada y requiere su tiempo de reposo.', false),
('locro', ARRAY['locro','locro criollo','locro pulsudo']::text[], 'El plato patrio por excelencia. Un guiso denso y pesado a base de maíz blanco, porotos, zapallo y diferentes cortes de carne y achuras.', 'Es un plato de altísima densidad calórica y grasa; reservarlo para ocasiones especiales, servite una porción medida y disfrutalo sabiendo que su digestión demandará tiempo. Tip extra: un toque de salsita picante (quiquirimí) con verdeo y pimentón por encima es el toque clásico que ayuda a levantar la digestión de las grasas.', 'Registra el nivel de pesadez o letargo posterior; al ser un plato sumamente pesado, exige una tarde tranquila sin exigencias físicas intensas.', false),
('pastel-polenta', ARRAY['pastel de polenta','pastel de maíz y carne','torre de polenta']::text[], 'Variante del clásico pastel de papas que reemplaza el puré por capas de polenta dorada con un corazón de carne picada sazonada.', 'Al igual que con el pastel de papas, el secreto para que no resulte pesado es moderar la capa de grasa añadida y dejar que la humedad de la carne haga el trabajo. Tip extra: un toque de queso gratinado arriba le aporta una costra crocante increíble sin alterar la digestibilidad.', 'Evalúa tu nivel de saciedad; combina la energía rápida de la polenta con la proteína de la carne, resultando en un plato muy rendidor.', false)
